import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int output_pad_d,
    int output_pad_h,
    int output_pad_w,
    int groups);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_conv_transpose3d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ y_ptr,
    int B,
    int IC,
    int DI,
    int HI,
    int WI,
    int OC,
    int DO,
    int HO,
    int WO,
    int KD,
    int KH,
    int KW,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int groups)
{
    constexpr int TILE_OC = 16;
    constexpr int TILE_X  = 16;

    __shared__ float weight_tile[TILE_OC][TILE_X];

    auto x_offset = [=](int b, int c, int d, int h, int w_idx) {
        return (((b * IC + c) * DI + d) * HI + h) * WI + w_idx;
    };
    auto w_offset = [=](int ic, int oc_l, int kd_, int kh_, int kw_) {
        return ((((ic * (OC / groups) + oc_l) * KD + kd_) * KH + kh_) * KW + kw_);
    };
    auto y_offset = [=](int b, int c, int d, int h, int w_idx) {
        return (((b * OC + c) * DO + d) * HO + h) * WO + w_idx;
    };

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int batch = int(blockIdx.z);
    const int oc = int(blockIdx.y) * TILE_OC + ty;
    const int spatial = int(blockIdx.x) * TILE_X + tx;

    const bool valid_oc = oc < OC;
    const bool valid_spatial = spatial < DO * HO * WO;
    const bool valid_output = valid_oc && valid_spatial;

    int od = 0;
    int oh = 0;
    int ow = 0;

    if (valid_spatial) {
        const int hw = HO * WO;
        od = spatial / hw;
        const int rem = spatial - od * hw;
        oh = rem / WO;
        ow = rem - oh * WO;
    }

    const int oc_per_group = OC / groups;
    const int ic_per_group = IC / groups;

    const int group = valid_oc ? (oc / oc_per_group) : 0;
    const int oc_local = valid_oc ? (oc - group * oc_per_group) : 0;
    const int ic_group_start = group * ic_per_group;

    float acc = 0.0f;

    for (int kd = 0; kd < KD; ++kd) {
        const int id_num = od + pad_d - kd;
        const bool d_valid =
            valid_spatial &&
            id_num >= 0 &&
            (id_num % stride_d == 0) &&
            (id_num / stride_d) < DI;
        const int id = id_num / stride_d;
        for (int kh = 0; kh < KH; ++kh) {
            const int ih_num = oh + pad_h - kh;
            const bool h_valid =
                valid_spatial &&
                ih_num >= 0 &&
                (ih_num % stride_h == 0) &&
                (ih_num / stride_h) < HI;
            const int ih = ih_num / stride_h;
            for (int kw = 0; kw < KW; ++kw) {
                const int iw_num = ow + pad_w - kw;
                const bool w_valid =
                    valid_spatial &&
                    iw_num >= 0 &&
                    (iw_num % stride_w == 0) &&
                    (iw_num / stride_w) < WI;
                const int iw = iw_num / stride_w;
                const bool valid_input = d_valid && h_valid && w_valid;
                for (int ic_tile = 0;
                     ic_tile < ic_per_group;
                     ic_tile += TILE_X) {
                    const int ic_local_load = ic_tile + tx;
                    const int ic_global_load =
                        ic_group_start + ic_local_load;
                    if (valid_oc && ic_local_load < ic_per_group) {
                        weight_tile[ty][tx] =
                            w_ptr[w_offset(
                                ic_global_load,
                                oc_local,
                                kd,
                                kh,
                                kw)];
                    } else {
                        weight_tile[ty][tx] = 0.0f;
                    }
                    __syncthreads();
                    if (valid_output && valid_input) {
                        for (int j = 0; j < TILE_X; ++j) {
                            const int ic_local = ic_tile + j;
                            if (ic_local < ic_per_group) {
                                acc += x_ptr[
                                    x_offset(
                                        batch,
                                        ic_group_start + ic_local,
                                        id,
                                        ih,
                                        iw)] *
                                    weight_tile[ty][j];
                            }
                        }
                    }
                    __syncthreads();
                }
            }
        }
    }

    if (valid_output) {
        if (bias_ptr != nullptr) {
            acc += bias_ptr[oc];
        }
        y_ptr[y_offset(batch, oc, od, oh, ow)] = acc;
    }
}


torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int output_pad_d,
    int output_pad_h,
    int output_pad_w,
    int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be 5D");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(stride_d > 0 && stride_h > 0 && stride_w > 0,
                "stride values must be positive");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    const int B  = int(x_c.size(0));
    const int IC = int(x_c.size(1));
    const int DI = int(x_c.size(2));
    const int HI = int(x_c.size(3));
    const int WI = int(x_c.size(4));

    const int OC = int(w_c.size(1)) * groups;
    const int KD = int(w_c.size(2));
    const int KH = int(w_c.size(3));
    const int KW = int(w_c.size(4));

    TORCH_CHECK(IC % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(OC % groups == 0, "output channels must be divisible by groups");
    TORCH_CHECK(int(w_c.size(0)) == IC, "invalid weight input channel dimension");
    TORCH_CHECK(pad_d >= 0 && pad_h >= 0 && pad_w >= 0,
                "padding values must be nonnegative");
    TORCH_CHECK(output_pad_d >= 0 &&
                output_pad_h >= 0 &&
                output_pad_w >= 0,
                "output_padding values must be nonnegative");
    TORCH_CHECK(output_pad_d < stride_d &&
                output_pad_h < stride_h &&
                output_pad_w < stride_w,
                "output_padding must be smaller than stride");

    const int DO = (DI - 1) * stride_d - 2 * pad_d + KD + output_pad_d;
    const int HO = (HI - 1) * stride_h - 2 * pad_h + KH + output_pad_h;
    const int WO = (WI - 1) * stride_w - 2 * pad_w + KW + output_pad_w;

    TORCH_CHECK(DO >= 0 && HO >= 0 && WO >= 0, "invalid output dimensions");

    auto y = torch::empty({B, OC, DO, HO, WO}, x_c.options());

    const float* bias_ptr = nullptr;
    torch::Tensor bias_c;
    if (bias.defined() && bias.numel() > 0) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
        TORCH_CHECK(bias.dim() == 1 && bias.size(0) == OC,
                    "invalid bias shape");
        bias_c = bias.contiguous();
        bias_ptr = bias_c.data_ptr<float>();
    }

    dim3 block(16, 16, 1);
    dim3 grid(
        (DO * HO * WO + 15) / 16,
        (OC + 15) / 16,
        B);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv_transpose3d_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        bias_ptr,
        y.data_ptr<float>(),
        B,
        IC,
        DI,
        HI,
        WI,
        OC,
        DO,
        HO,
        WO,
        KD,
        KH,
        KW,
        stride_d,
        stride_h,
        stride_w,
        pad_d,
        pad_h,
        pad_w,
        groups);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE conv_transpose3d launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose3d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1, 1),
        padding: tuple = (0, 0, 0),
        output_padding: tuple = (0, 0, 0),
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

        self._stride = tuple(stride)
        self._padding = tuple(padding)
        self._output_padding = tuple(output_padding)
        self._groups = groups
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )

        return self._ext.cute_conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            bias,
            int(self._stride[0]),
            int(self._stride[1]),
            int(self._stride[2]),
            int(self._padding[0]),
            int(self._padding[1]),
            int(self._padding[2]),
            int(self._output_padding[0]),
            int(self._output_padding[1]),
            int(self._output_padding[2]),
            int(self._groups),
        )

