import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
    int pad_w,
    int output_pad_d,
    int output_pad_h,
    int output_pad_w,
    int groups);
