cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAException.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;
__device__ __forceinline__
size_t x_offset(
    int b, int c, int d, int h, int w,
    int IC, int DI, int HI, int WI)
{
    return (((size_t)b * IC + c) * DI + d) * HI * WI
         + (size_t)h * WI + w;
}
__device__ __forceinline__
size_t w_offset(
    int ic, int oc_local, int kd, int kh, int kw,
    int OC_per_group, int KD, int KH, int KW)
{
    return ((((size_t)ic * OC_per_group + oc_local) * KD + kd)
            * KH + kh) * KW + kw;
}
__device__ __forceinline__
size_t y_offset(
    int b, int oc, int od, int oh, int ow,
    int OC, int DO, int HO, int WO)
{
    return (((size_t)b * OC + oc) * DO + od) * HO * WO
         + (size_t)oh * WO + ow;
}

__global__ void cute_conv_transpose3d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ bias_ptr,
    float* __restrict__ y_ptr,
    int B,
    int IC,
    int DI,
    int HI,
    int WI,
    int OC,
    int DO,
    int HO,
    int WO,
    int KD,
    int KH,
    int KW,
    int stride_d,
    int stride_h,
    int stride_w,
    int pad_d,
    int pad_h,
